<?php
namespace App\Http\Controllers\Public\Business\Admin\Purchase;
use App\Http\Controllers\Controller;
use App\Models\Purchase\PurchaseOrder;
use App\Models\Purchase\PurchaseOrderItem;
use App\Models\Purchase\PurchaseOrderReceipt;
use App\Models\Configurations\Variant;
use App\Services\Access;
use App\Services\Lists;
use App\Services\Purchases;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
class PurchaseOrderController extends Controller {
 public function index(Request $r,Access $a){$v=$a->check($r,'purchasing','purchase-orders','po-list');$v['title']='Purchase Orders';$v['records']=Lists::page(PurchaseOrder::where('business_id',$v['business']->id),$r,['id'=>'number','po_no'=>'text','status'=>'text','supplier_id'=>'number','total'=>'number','created_at'=>'date']);return view('public.business.admin.retail.purchase_orders.index',$v);}
 public function create(Request $r,Access $a){$v=$a->check($r,'purchasing','purchase-orders','new-po');$v['title']='New Purchase Order';$v['variants']=Variant::with('product')->where('business_id',$v['business']->id)->where('is_active',true)->get();$v['suppliers']=DB::table('config_suppliers')->where('business_id',$v['business']->id)->where('is_active',true)->get();return view('public.business.admin.retail.purchase_orders.form',$v);}
 public function store(Request $r,Access $a){$v=$a->check($r,'purchasing','purchase-orders','new-po','create');$b=$v['business'];$d=$r->validate(['supplier_id'=>['required',Rule::exists('config_suppliers','id')->where('business_id',$b->id)],'notes'=>'nullable|string|max:1000','items'=>'required|array|min:1|max:100','items.*.variant_id'=>'required|integer','items.*.quantity'=>'required|numeric|gt:0|max:999999','items.*.cost'=>'required|numeric|min:0|max:99999999']);$po=DB::transaction(function()use($b,$d){$lines=[];$total=0;foreach($d['items'] as $row){$variant=Variant::where('business_id',$b->id)->findOrFail($row['variant_id']);$qty=round((float)$row['quantity'],3);$cost=round((float)$row['cost'],2);$line=round($qty*$cost,2);$total+=$line;$lines[]=[$variant->id,$qty,$cost,$line];}$po=PurchaseOrder::create(['business_id'=>$b->id,'po_no'=>getGenerateCode(PurchaseOrder::where('business_id',$b->id),'po_no','PO'),'supplier_id'=>$d['supplier_id'],'notes'=>$d['notes']??null,'status'=>'draft','total'=>round($total,2)]);foreach($lines as [$variant,$qty,$cost,$line])PurchaseOrderItem::create(['business_id'=>$b->id,'purchase_order_id'=>$po->id,'variant_id'=>$variant,'quantity'=>$qty,'cost'=>$cost,'total'=>$line]);return $po;});return redirect()->route('business.admin.retail.purchase_orders.show',$po->id)->with('success',t('Purchase order created.','ক্রয় আদেশ তৈরি হয়েছে।'));}
 public function show(Request $r,int $record,Access $a){$v=$a->check($r,'purchasing','purchase-orders','po-list');$v['po']=PurchaseOrder::with(['items','receipts'])->where('business_id',$v['business']->id)->findOrFail($record);return view('public.business.admin.retail.purchase_orders.show',$v);}
 public function approve(Request $r,int $record,Access $a){$v=$a->check($r,'purchasing','purchase-orders','po-list','update');$po=PurchaseOrder::where('business_id',$v['business']->id)->findOrFail($record);abort_unless($po->status==='draft',422,'Only draft orders can be approved.');$po->update(['status'=>'approved']);return back()->with('success',t('Approved.','অনুমোদিত।'));}
 public function receive(Request $r,int $record,Access $a,Purchases $purchases){$v=$a->check($r,'purchasing','receiving','new-grn','create');$b=$v['business'];$data=$r->validate(['items'=>'required|array|min:1','items.*.id'=>'required|integer','items.*.quantity'=>'required|numeric|min:0|max:999999','pay_amount'=>'nullable|numeric|min:0','payment_method'=>'nullable|in:cash,bank']);DB::transaction(function()use($b,$record,$data,$purchases){$po=PurchaseOrder::where('business_id',$b->id)->lockForUpdate()->findOrFail($record);abort_unless(in_array($po->status,['approved','partial'],true),422,'PO must be approved and not yet fully received.');$rows=[];$seen=[];foreach($data['items'] as $line){$id=(int)$line['id'];if(isset($seen[$id]))throw ValidationException::withMessages(['items'=>'Duplicate line.']);$seen[$id]=true;$item=PurchaseOrderItem::where('business_id',$b->id)->where('purchase_order_id',$po->id)->lockForUpdate()->findOrFail($id);$qty=round((float)$line['quantity'],3);if($qty>round((float)$item->quantity-(float)$item->received_quantity,3)+.00001)throw ValidationException::withMessages(['items'=>'Receipt exceeds remaining PO quantity.']);if($qty>0)$rows[]=[$item,$qty];}if(!$rows)throw ValidationException::withMessages(['items'=>'Enter at least one receipt quantity.']);$purchase=$purchases->create($b,['supplier_id'=>$po->supplier_id,'notes'=>'Received against '.$po->po_no,'items'=>array_map(fn($x)=>['variant_id'=>$x[0]->variant_id,'quantity'=>$x[1],'cost'=>$x[0]->cost],$rows),'pay_amount'=>$data['pay_amount']??0,'payment_method'=>$data['payment_method']??'cash']);PurchaseOrderReceipt::create(['business_id'=>$b->id,'purchase_order_id'=>$po->id,'purchase_id'=>$purchase->id]);foreach($rows as [$item,$qty])$item->increment('received_quantity',$qty);$all=PurchaseOrderItem::where('purchase_order_id',$po->id)->whereColumn('received_quantity','<','quantity')->exists();$po->update(['status'=>$all?'partial':'received']);});return back()->with('success',t('Stock received and accounts posted.','স্টক গ্রহণ ও হিসাব পোস্ট হয়েছে।'));}
}
